  + '    id,\n'
  + '    value = null,\n'
  + '    defaultValue = null,\n'
  + '\n'
  + '    options,\n'
  + '    placeholder = "Select options",\n'
  + '    disabled = false,\n'
  + '\n'
  + '    onChange,\n'
  + '\n'
  + '    ...rest\n'
  + '  } = props;\n'
  + '\n'
  + '  const jss = useJss();\n'
  + '\n'
  + '  const [triggerEl, setTriggerEl] = useState<HTMLDivElement | null>(null);\n'
  + '  const [triggerWidth, setTriggerWidth] = useState(0);\n'
  + '  const internalValueRef = useRef<V[] | null>(defaultValue);\n'
  + '  const showLabelsRef = useRef<string[] | null>(null);\n'
  + '\n'
  + '  const updateShowLabelsByInternalValue = useCallback(() => {\n'
  + '    if (internalValueRef.current != null) {\n'
  + '      showLabelsRef.current = internalValueRef.current\n'
  + '        .map((v) => options.find((o) => o.value === v)?.label ?? null)\n'
  + '        .filter((l) => l != null) as string[];\n'
  + '    } else {\n'
  + '      showLabelsRef.current = null;\n'
  + '    }\n'
  + '  }, [options]);\n'
  + '\n'
  + '  // Update internal value when `value` prop changes.\n'
  + '  useEffect(() => {\n'
  + '    if (value !== internalValueRef.current) {\n'
  + '      internalValueRef.current = value ?? null;\n'
  + '    }\n'
  + '  }, [value]);\n'
  + '\n'
  + '  // Update trigger width on mount and resize.\n'
  + '  useLayoutEffect(() => {\n'
  + '    if (triggerEl) {\n'
  + '      setTriggerWidth(triggerEl.offsetWidth);\n'
  + '\n'
  + '      const ro = new ResizeObserver(() => {\n'
  + '        const width = triggerEl.offsetWidth;\n'
  + '        if (width) {\n'
  + '          setTriggerWidth(triggerEl.offsetWidth);\n'
  + '        }\n'
  + '      });\n'
  + '      ro.observe(triggerEl);\n'
  + '\n'
  + '      return () => {\n'
  + '        ro.disconnect();\n'
  + '      };\n'
  + '    }\n'
