sourceCode['multi-select-trigger.tsx'] = ''
  + 'import classNames from "classnames";\n'
  + 'import { ChevronsUpDown } from "lucide-react";\n'
  + 'import {\n'
  + '  createContext,\n'
  + '  type FC,\n'
  + '  type Ref,\n'
  + '  useContext,\n'
  + '} from "react";\n'
  + '\n'
  + 'import { useJss, useTheme } from "@/components/CopyUiProvider";\n'
  + 'import {\n'
  + '  extractStylesProps,\n'
  + '  IbsBase,\n'
  + '  type IbsBaseRootProps,\n'
  + '} from "@/components/IbsBase";\n'
  + '\n'
  + 'import styles from "./multi-select-trigger.module.css";\n'
  + '\n'
  + 'type MultiSelectTriggerProps = {\n'
  + '  id?: string;\n'
  + '  ref: Ref<HTMLDivElement>;\n'
  + '  className?: string;\n'
  + '\n'
  + '  placeholder: string;\n'
  + '  disabled: boolean;\n'
  + '  isOpen: boolean;\n'
  + '  showLabels: string[] | null;\n'
  + '\n'
  + '  onToggle: () => void;\n'
  + '};\n'
  + '\n'
  + 'const MultiSelectTrigger: FC<MultiSelectTriggerProps> = (props) => {\n'
  + '  const {\n'
  + '    id,\n'
  + '    ref,\n'
  + '    className,\n'
  + '    placeholder,\n'
  + '    disabled,\n'
  + '    isOpen,\n'
  + '    showLabels,\n'
  + '    onToggle,\n'
  + '  } = props;\n'
  + '\n'
  + '  const ibsBaseProps = useContext(TriggerIbsBasePropsContext);\n'
  + '\n'
  + '  const { stx: baseStyleStx } = extractStylesProps(ibsBaseProps ?? {});\n'
  + '\n'
  + '  const theme = useTheme();\n'
  + '  const jss = useJss();\n'
  + '\n'
  + '  const handleKeyDown = (e: React.KeyboardEvent) => {\n'
  + '    if (disabled) return;\n'
  + '\n'
  + '    if (e.key === "Enter" || e.key === " ") {\n'
  + '      e.preventDefault();\n'
  + '      onToggle();\n'
  + '    }\n'
  + '  };\n'
  + '\n'
  + '  const triggerStx = jss.hash({\n'
  + '    "--multiSelectTrigger-bdColor": theme.colors.gray["400"],\n'
  + '    "--multiSelectTrigger-bdRadius": "0.5rem",\n'
  + '    "--multiSelectTrigger-placeholderColor": theme.colors.gray["600"],\n'
  + '    "--multiSelectTrigger-pl": "var(--multiSelect-triggerPl)",\n'
  + '    "--multiSelectTrigger-iconColor": theme.colors.gray["600"],\n'
  + '\n'
  + '    "--multiSelectTrigger-disabled-color": theme.colors.gray["600"],\n'
  + '    "--multiSelectTrigger-disabled-bgColor": theme.colors.gray["000"],\n'
  + '    "--multiSelectTrigger-disabled-bdColor": theme.colors.gray["200"],\n'
  + '\n'
  + '    "--multiSelectTrigger-focus-bdColor": theme.colors.blue["700"],\n'
  + '  });\n'
  + '\n'
  + '  return (\n'
  + '    <IbsBase\n'
  + '      id={id}\n'
  + '      ref={ref}\n'
  + '      className={classNames(\n'
  + '        styles.selectTrigger,\n'
  + '        triggerStx,\n'
  + '        baseStyleStx,\n'
  + '        className,\n'
  + '      )}\n'
  + '      onClick={() => !disabled && onToggle()}\n'
  + '      tabIndex={0}\n'
  + '      onKeyDown={handleKeyDown}\n'
  + '      role="combobox"\n'
  + '      aria-haspopup="listbox"\n'
  + '      aria-expanded={isOpen ? "true" : "false"}\n'
  + '      data-value-picked={showLabels == null ? undefined : "true"}\n'
  + '      data-disabled={disabled ? "true" : undefined}\n'
  + '      data-opened={isOpen ? "true" : undefined}\n'
  + '    >\n'
  + '      <IbsBase.Wrapper>\n'
  + '        <span className={styles.selectLabelsContainer}>\n'
  + '          {showLabels !== null\n'
  + '            ? showLabels.map((l) => <MultiSelectLabel key={l} label={l} />)\n'
  + '            : placeholder}\n'
  + '        </span>\n'
  + '      </IbsBase.Wrapper>\n'
  + '      <IbsBase.RightSection className={styles.selectIcon}>\n'
  + '        <ChevronsUpDown size="50%" />\n'
  + '      </IbsBase.RightSection>\n'
  + '    </IbsBase>\n'
  + '  );\n'
  + '};\n'
  + '\n'
  + 'MultiSelectTrigger.displayName = "MultiSelect.Trigger";\n'
  + '\n'
  + 'const MultiSelectLabel = ({ label }: { label: string }) => {\n'
  + '  const theme = useTheme();\n'
  + '  const jss = useJss();\n'
  + '\n'
  + '  const labelStx = jss.hash({\n'
  + '    "--multiSelectTrigger-labelP": "0.125rem 0.375rem",\n'
  + '    "--multiSelectTrigger-labelBgColor": theme.colors.gray["100"],\n'
  + '  });\n'
  + '\n'
  + '  return (\n'
  + '    <span className={classNames(styles.selectLabel, labelStx)}>{label}</span>\n'
  + '  );\n'
  + '};\n'
  + '\n'
  + 'const TriggerIbsBasePropsContext = createContext<IbsBaseRootProps | null>(null);\n'
  + '\n'
  + 'export { MultiSelectTrigger, TriggerIbsBasePropsContext };\n'
  ;

